{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver vejledningens eksempler korrekt: lægefaglige oplysninger om udrednings- og behandlingsforløb samt aktuelle symptomer, epikriser og journalnotater, støtteafgørelser og skånehensyn. Den personlige redegørelse nævnes som en mulighed, når dokumentation ikke findes. Svaret indeholder ingen af rubrikkens væsentlige fejl, fx at alt er obligatorisk, eller at redegørelsen erstatter det lægefaglige minimum."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med: de seneste lægefaglige oplysninger og sygehistorik, udrednings- og behandlingsforløb samt symptomer, epikriser og journalnotater med støtte og skånehensyn som supplement, og den personlige redegørelse, når dokumentation mangler."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret er en direkte opremsning af, hvilken dokumentation en ansøger med medfødt funktionsnedsættelse kan sende, og det er netop det, der spørges om."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken vejledning, lov eller bekendtgørelse."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det ikke kan vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Indholdet findes i vejledningens afsnit 4.3. Svaret tilføjer ingen ny regel, betingelse eller retsvirkning."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Rubrikken kræver to forbehold: at de seneste foreliggende oplysninger kan være ældre, og at en personlig redegørelse supplerer og ikke ophæver det lægefaglige dokumentationsminimum. Svaret har ingen af dem. Det siger ikke, at ældre oplysninger kan være de seneste tilgængelige. Det siger heller ikke, at redegørelsen ikke erstatter lægefaglig dokumentation. Det siger kun, at redegørelsen kan bruges, hvis støtte- eller skånehensynsdokumentation mangler."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en enkel og intern konsistent opremsning. Den afsluttende bemærkning om den personlige redegørelse følger af opremsningen."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger konsekvent 'kan' og 'eventuelle' og gør ingen eksempler til krav. Det svarer til vejledningens formuleringer ('kan f.eks. være') og undgår de absolutte formuleringer, rubrikken advarer imod."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "partial",
      "reason": "Svaret dækker sygehistorik, journalnotater og den personlige redegørelse. Det nævner ikke, at medfødt funktionsnedsættelse ofte betyder, at nyere dokumentation om aktuelt funktionsniveau mangler, og det nævner ikke de eksemplificerende diagnoser eller at listen ikke er udtømmende."
    },
    "A35": {
      "label": "yes",
      "reason": "Svaret dækker næsten alle alternative dokumentationsformer i passagen: lægefaglige oplysninger om forløb og symptomer, epikriser og journalnotater, støtteafgørelser, støtteforanstaltninger og skånehensyn samt den personlige redegørelse, hvis dokumentation ikke findes. Svaret omtaler ikke tidspunktet 'på ansøgningstidspunktet'."
    }
  },
  "overall_notes": "Indholdet er korrekt og komplet i forhold til vejledningens afsnit 4.3 og rubrikkens kritiske elementer. Svaret nævner dog ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable. Det mangler også de to krævede forbehold: at de seneste oplysninger kan være ældre, og at den personlige redegørelse supplerer og ikke erstatter det lægefaglige minimum."
}

